//! Roc modules from schemas.
//!
//! Roc has no build scripts, so the modules are generated by `haus-gen roc`
//! and checked in, like protobuf output. Each schema becomes one module with
//! a type, a decoder and an encoder per named type:
//!
//! | haus                       | Roc                                           |
//! |----------------------------|-----------------------------------------------|
//! | `{ a: T, b?: U }`          | `{ a : T, b : [Missing, Present(U)] }`        |
//! | `< A \| B T \| C { … } >`  | `[A, B(T), C({ … }), Unknown(Str, List(Value))]` (open) |
//! | `Maybe a`, `Result e a`    | `[None, Some(a)]`, `Try(a, e)`                |
//! | `Array a`, `Map v`         | `List(a)`, `List((Str, v))`                   |
//! | `Int`, `Int8`…`UInt64`     | `Int` (any size, exact digits), `I8`…`U64`    |
//! | `Float32`, `Float64`       | `F32`, `F64`                                  |
//! | `Decimal`, std/time        | `Str` (exact text; std/time checked)          |
//! | `< >`                      | `[Bare(Str), Other(Str, List(Value))]`        |
//! | `Any`                      | `Value`                                       |
//! | `Secret a`                 | `Secret(a)` (`<redacted>` when inspected)     |
//! | `type Pair a = …`          | `Pair(a)`, with `decode_pair(v, decode_a)`    |
//!
//! Named variants are nominal (`:=`), so they can be recursive, and so are
//! records and other types that refer to themselves (`Tree := { children :
//! List(Tree) }`). A type named like a Roc builtin or an imported module
//! (`List`, `F64`, `Box`, `Value`) gets a `_` at the end in Roc (`List_`);
//! its functions keep their names (`decode_list`). A codec is a Roc module
//! with `Target`, `decode : Base -> Try(Target, Str)` and `encode : Target -> Base`.
//!
//! Roc has no deprecation marker: a `@deprecated` type, field or tag gets a
//! line in the type's doc comment (`## Deprecated field `mail`: use email.`).

use crate::codegen::STD_TIME;
use crate::packages::{Manifest, Package, Packages};
use crate::schema::{self, Attribute, Case, Field, Ty, TypeDef, deprecation, error};
use crate::{Error, Result, read};
use std::collections::{HashMap, HashSet};
use std::fmt::Write as _;
use std::fs;
use std::path::{Path, PathBuf};

/// How to generate a Roc module.
#[derive(Debug, Clone, Default)]
pub struct RocConfig {
    /// Codecs: a type's id, and the Roc module of its codec.
    codecs: Vec<(String, String)>,
    /// Schema packages: their directory, and the alias the app gives their Roc package.
    packages: Vec<(PathBuf, String)>,
}

impl RocConfig {
    pub fn new() -> RocConfig {
        RocConfig::default()
    }

    /// Use the codec module `module` for the type with this id.
    pub fn codec(mut self, id: impl Into<String>, module: impl Into<String>) -> RocConfig {
        self.codecs.push((id.into(), module.into()));
        self
    }

    /// The schema package in `dir`, imported in Roc under `alias` (`money: "…/main.roc"`).
    pub fn package(mut self, dir: impl Into<PathBuf>, alias: impl Into<String>) -> RocConfig {
        self.packages.push((dir.into(), alias.into()));
        self
    }

    /// The module for an application's schema file, named `module`, with id `id`.
    pub fn generate(&self, schema: &Path, module: &str, id: &str) -> Result<String> {
        let packages = self.packages.iter().try_fold(Packages::none(), |all, (dir, alias)| all.with(dir, alias))?;
        generate(&read(schema)?, module, id, &self.codecs, &packages).map_err(|e| e.in_file(schema))
    }

    /// The module of the schema package in `dir`: its name and ids come from the manifest.
    pub fn generate_package(&self, dir: &Path) -> Result<(String, String)> {
        let manifest = Manifest::read(dir)?;
        let module = package_module(&manifest.name);
        let code = self.generate(&dir.join(&manifest.schema), &module, &manifest.id())?;
        Ok((module, code))
    }

    /// Write [`RocConfig::generate`]'s module to `out`.
    pub fn write(&self, schema: &Path, module: &str, id: &str, out: &Path) -> Result<()> {
        let code = self.generate(schema, module, id)?;
        fs::write(out, code).map_err(|e| Error::at(out, e))
    }
}

/// `@haus/money` → `HausMoney`: the organisation too, so the module's name
/// never clashes with a type in it (`HausMoney.Money`).
fn package_module(name: &str) -> String {
    pascal(name)
}

/// The Roc module for a schema.
pub fn generate(
    text: &str,
    module: &str,
    id: &str,
    codecs: &[(String, String)],
    packages: &Packages,
) -> Result<String> {
    let file = schema::parse(text)?;
    let mut imports = HashMap::new();
    let mut roc_imports = vec!["haus.Value".to_owned(), "haus.Decode".to_owned(), "haus.Encode".to_owned()];
    for imp in &file.imports {
        let fail = |reason: String| Error::from(error(text, imp.pos, reason));
        if imp.module == "std/time" {
            for (n, _) in &imp.names {
                if !STD_TIME.contains(&n.as_str()) {
                    return Err(fail(format!("std/time has no type {n}")));
                }
                imports.insert(n.clone(), Source::Time);
            }
            continue;
        }
        let name = imp.module.rsplit_once('@').filter(|(n, _)| !n.is_empty()).map_or(imp.module.as_str(), |(n, _)| n);
        let pkg: &Package = packages.find(name).map_err(fail)?;
        let m = package_module(&pkg.manifest.name);
        roc_imports.push(format!("{}.{m}", pkg.krate));
        for (n, _) in &imp.names {
            if !pkg.types.contains_key(n) {
                return Err(fail(format!("{name} has no type {n}")));
            }
            imports.insert(n.clone(), Source::Package { module: m.clone(), id: format!("{}#{n}", pkg.manifest.id()) });
        }
    }
    let ids: HashSet<String> = file
        .types
        .iter()
        .map(|d| format!("{id}#{}", d.name))
        .chain(imports.values().filter_map(|s| match s {
            Source::Package { id, .. } => Some(id.clone()),
            Source::Time => None,
        }))
        .chain(imports.keys().filter(|n| matches!(imports[*n], Source::Time)).map(|n| format!("std/time#{n}")))
        .collect();
    if let Some((cid, _)) = codecs.iter().find(|(cid, _)| !ids.contains(cid)) {
        return Err(Error::new(format!("a codec for {cid}, but the schema has no such type")));
    }
    roc_imports.extend(codecs.iter().map(|(_, m)| m.clone()));
    roc_imports.dedup();

    // Names taken in Roc: builtin types, imported modules and the module itself.
    let taken: HashSet<String> = BUILTIN_TYPES
        .iter()
        .map(|t| (*t).to_owned())
        .chain(["Int".to_owned(), module.to_owned()])
        .chain(roc_imports.iter().map(|i| i.rsplit('.').next().unwrap_or(i).to_owned()))
        .collect();
    let schema_names: HashSet<&str> = file.types.iter().map(|d| d.name.as_str()).collect();
    let roc_names = file
        .types
        .iter()
        .map(|d| {
            let mut name = d.name.clone();
            while taken.contains(&name) || (name != d.name && schema_names.contains(name.as_str())) {
                name.push('_');
            }
            (d.name.clone(), name)
        })
        .collect();
    let defs: HashMap<&str, &TypeDef> = file.types.iter().map(|d| (d.name.as_str(), d)).collect();
    let recursive = file.types.iter().filter(|d| refers_to_itself(d, &defs)).map(|d| d.name.clone()).collect();

    let mut g = Gen {
        text,
        id,
        defs,
        imports,
        codecs: codecs.iter().cloned().collect(),
        fresh: 0,
        helpers: Vec::new(),
        names: file.types.iter().map(|d| d.name.clone()).collect(),
        uses_int: false,
        uses_secret: false,
        roc_names,
        recursive,
        params: Vec::new(),
    };
    let items = file.types.iter().map(|d| g.define(d)).collect::<Result<Vec<_>>>()?;
    if g.uses_secret {
        roc_imports.insert(3, "haus.Secret".to_owned());
    }
    if g.uses_int {
        roc_imports.insert(3, "haus.Int".to_owned());
    }
    let mut out = format!("## Generated by haus-gen from {id}. Don't edit.\n");
    for i in &roc_imports {
        let _ = writeln!(out, "import {i}");
    }
    let _ = write!(out, "\n{module} := [].{{\n");
    for item in items.iter().chain(&g.helpers) {
        let _ = writeln!(out, "{item}");
    }
    out.push_str("}\n");
    Ok(out)
}

/// Where an imported type comes from.
enum Source {
    Time,
    Package { module: String, id: String },
}

/// Decoding or encoding `x`: a function's name, or an expression with `{x}`.
#[derive(Clone)]
enum F {
    Name(String),
    Template(String),
}

/// A Roc type, its decoder and its encoder.
struct R {
    ty: String,
    de: F,
    en: F,
}

impl R {
    fn named(ty: &str, de: &str, en: &str) -> R {
        R { ty: ty.into(), de: F::Name(de.into()), en: F::Name(en.into()) }
    }
}

struct Gen<'a> {
    text: &'a str,
    id: &'a str,
    defs: HashMap<&'a str, &'a TypeDef>,
    imports: HashMap<String, Source>,
    codecs: HashMap<String, String>,
    /// For fresh lambda parameters (Roc doesn't allow shadowing).
    fresh: usize,
    /// Decoders and encoders of inline types.
    helpers: Vec<String>,
    names: HashSet<String>,
    /// Whether the module needs `haus.Int`.
    uses_int: bool,
    /// Whether the module needs `haus.Secret`.
    uses_secret: bool,
    /// Each schema type's name in Roc (`List` → `List_`).
    roc_names: HashMap<String, String>,
    /// Types that refer to themselves, so they are nominal in Roc.
    recursive: HashSet<String>,
    /// The parameters of the definition being generated, and their names in Roc.
    params: Vec<(String, String)>,
}

impl Gen<'_> {
    fn fail<T>(&self, pos: usize, reason: impl Into<String>) -> Result<T> {
        Err(error(self.text, pos, reason).into())
    }

    /// A type parameter in Roc: `a`, and its decoder `decode_a`, which must
    /// not be the decoder of a type (`type A`, `type Box a`): then `a_`.
    fn param_name(&self, param: &str) -> String {
        let mut name = field_name(param);
        while self.defs.keys().any(|d| snake(d) == name) {
            name.push('_');
        }
        name
    }

    /// `f` as a function value.
    fn value(&mut self, f: &F) -> String {
        match f {
            F::Name(n) => n.clone(),
            F::Template(t) => {
                self.fresh += 1;
                let x = format!("x{}", self.fresh);
                format!("|{x}| {}", t.replace("{x}", &x))
            }
        }
    }

    /// The type, decoder and encoder of a definition.
    fn define(&mut self, def: &TypeDef) -> Result<String> {
        self.params = def.params.iter().map(|p| (p.clone(), self.param_name(p))).collect();
        let deprecations = deprecations(def);
        let doc: String = def
            .doc
            .lines()
            .chain(["", &format!("haus type `{}#{}`.", self.id, def.name)])
            .chain(deprecations.iter().map(String::as_str))
            .skip_while(|l| l.is_empty())
            .fold(String::new(), |mut out, l| {
                let _ = writeln!(out, "\t##{}{l}", if l.is_empty() { "" } else { " " });
                out
            });
        if let Ty::Name { name, args, .. } = &def.ty
            && name == "Stream"
        {
            let item = args.first().map_or(String::new(), |a| match a {
                Ty::Name { name, .. } => name.clone(),
                _ => String::new(),
            });
            return Ok(format!("{doc}\t# A stream of {item}: read it with Stream and decode_{}.\n", snake(&item)));
        }
        let snake_name = snake(&def.name);
        // `Pair(a)`; records and other types that refer to themselves are nominal.
        let head = match self.params.as_slice() {
            [] => self.roc_names[&def.name].clone(),
            ps => format!(
                "{}({})",
                self.roc_names[&def.name],
                ps.iter().map(|(_, p)| p.as_str()).collect::<Vec<_>>().join(", ")
            ),
        };
        let is = if self.recursive.contains(&def.name) { ":=" } else { ":" };
        let (decl, decode, encode) = match &def.ty {
            Ty::Record { closed, fields, .. } => {
                let (ty, de, en) = self.record(&def.name, *closed, fields)?;
                (format!("{head} {is} {ty}"), de, en)
            }
            Ty::Variant { closed: false, cases, .. } if cases.is_empty() => {
                let r = any_tag();
                (format!("{head} : {}", r.ty), self.call_body(&r.de), self.call_body(&r.en))
            }
            Ty::Variant { closed, cases, .. } => {
                let (ty, de, en) = self.variant(&def.name, *closed, cases)?;
                (format!("{head} := {ty}"), de, en)
            }
            ty if self.recursive.contains(&def.name) => {
                // Roc allows recursion only through a tag or a record field:
                // `type Nested = Array Nested` is `Nested := [Nested(List(Nested))]`.
                let r = self.lower(ty, &def.name)?;
                let tag = &def.name;
                let en = match &r.en {
                    F::Name(f) => format!("{f}(x)"),
                    F::Template(t) => t.replace("{x}", "x"),
                };
                (
                    format!("{head} := [{tag}({})]", r.ty),
                    format!("Ok({tag}({}?))", self.call_body(&r.de)),
                    format!("match v {{\n\t\t{tag}(x) => {en}\n\t}}"),
                )
            }
            ty => {
                let r = self.lower(ty, &def.name)?;
                (format!("{head} : {}", r.ty), self.call_body(&r.de), self.call_body(&r.en))
            }
        };
        // A decoder and an encoder for each parameter; `_` for those the type doesn't use.
        let used = params_in(&def.ty);
        let p = Params::new(self.params.iter().map(|(h, p)| (p.clone(), used.contains(h))));
        self.params.clear();
        let v = encoded_var(&def.ty);
        Ok(format!(
            "{doc}\t{decl}\n\n\tdecode_{snake_name} : Value{} -> Try({head}, Decode.Error)\n\tdecode_{snake_name} = |v{}| {decode}\n\n\
             \tencode_{snake_name} : {head}{} -> Value\n\tencode_{snake_name} = |{v}{}| {encode}\n",
            p.de_types, p.de_args, p.en_types, p.en_args
        ))
    }

    /// The body of a function `|v| …` that applies `f` to `v`.
    fn call_body(&self, f: &F) -> String {
        match f {
            F::Name(n) => format!("{n}(v)"),
            F::Template(t) => t.replace("{x}", "v"),
        }
    }

    /// A Roc type for a type expression; `hint` names inline types.
    fn lower(&mut self, ty: &Ty, hint: &str) -> Result<R> {
        match ty {
            Ty::Param { name, pos } => match self.params.iter().find(|(h, _)| h == name) {
                Some((_, p)) => {
                    Ok(R { ty: p.clone(), de: F::Name(format!("decode_{p}")), en: F::Name(format!("encode_{p}")) })
                }
                None => self.fail(*pos, format!("unknown type parameter {name}")),
            },
            Ty::Record { .. } | Ty::Variant { .. } => self.inline(ty, hint),
            Ty::Name { name, args, pos } => self.named(name, args, *pos, hint),
        }
    }

    fn named(&mut self, name: &str, args: &[Ty], pos: usize, hint: &str) -> Result<R> {
        let arity = |n: usize| (args.len() != n).then(|| format!("{name} takes {n} argument(s), found {}", args.len()));
        let (id, base) = if let Some(def) = self.defs.get(name) {
            let s = snake(name);
            let roc = self.roc_names[name].clone();
            let id = format!("{}#{name}", self.id);
            if def.params.is_empty() {
                (id, R::named(&roc, &format!("decode_{s}"), &format!("encode_{s}")))
            } else {
                // A generic type, applied: `Pair Int` is `Pair(Int)`, decoded with `decode_pair(v, Decode.int)`.
                if let Some(reason) = arity(def.params.len()) {
                    return self.fail(pos, reason);
                }
                if self.codecs.contains_key(&id) {
                    return self.fail(pos, format!("a codec for the generic type {name} is not supported in Roc"));
                }
                let rs = args
                    .iter()
                    .enumerate()
                    .map(|(i, a)| self.lower(a, &format!("{hint}{}", i + 1)))
                    .collect::<Result<Vec<_>>>()?;
                let ty = format!("{roc}({})", rs.iter().map(|r| r.ty.as_str()).collect::<Vec<_>>().join(", "));
                let (mut de, mut en) = (format!("decode_{s}({{x}}"), format!("encode_{s}({{x}}"));
                for r in &rs {
                    let (d, e) = (self.value(&r.de), self.value(&r.en));
                    let _ = write!(de, ", {d}");
                    let _ = write!(en, ", {e}");
                }
                return Ok(R { ty, de: F::Template(de + ")"), en: F::Template(en + ")") });
            }
        } else if let Some(source) = self.imports.get(name) {
            match source {
                Source::Time => (
                    format!("std/time#{name}"),
                    R::named("Str", &format!("Decode.time(\"{name}\")"), &format!("Encode.time(\"{name}\")")),
                ),
                Source::Package { module, id } => {
                    let s = snake(name);
                    (
                        id.clone(),
                        R::named(
                            &format!("{module}.{name}"),
                            &format!("{module}.decode_{s}"),
                            &format!("{module}.encode_{s}"),
                        ),
                    )
                }
            }
        } else {
            return self.prelude(name, args, pos, hint);
        };
        if let Some(reason) = arity(0) {
            return self.fail(pos, reason);
        }
        Ok(match self.codecs.get(&id).cloned() {
            None => base,
            Some(codec) => {
                let de = self.value(&base.de);
                let en = match &base.en {
                    F::Name(n) => format!("{n}({codec}.encode({{x}}))"),
                    F::Template(t) => t.replace("{x}", &format!("{codec}.encode({{x}})")),
                };
                R {
                    ty: format!("{codec}.Target"),
                    de: F::Template(format!("Decode.codec({{x}}, {de}, {codec}.decode)")),
                    en: F::Template(en),
                }
            }
        })
    }

    fn prelude(&mut self, name: &str, args: &[Ty], pos: usize, hint: &str) -> Result<R> {
        let number = |ty: &str, de: &str| R {
            ty: ty.into(),
            de: F::Name(de.into()),
            en: F::Template("Num({x}.to_str())".into()),
        };
        let expect = |n: usize| (args.len() == n).then_some(()).ok_or(());
        let r = match name {
            "Bool" => R::named("Bool", "Decode.bool", "Encode.bool"),
            "String" => R::named("Str", "Decode.str", "Encode.str"),
            "Bytes" => R::named("List(U8)", "Decode.bytes", "Encode.bytes"),
            "Decimal" => R::named("Str", "Decode.decimal", "Encode.decimal"),
            "Float32" => R::named("F32", "Decode.f32", "Encode.f32"),
            "Float64" => R::named("F64", "Decode.f64", "Encode.f64"),
            "Any" => R::named("Value", "Decode.any", "Encode.any"),
            "Secret" if expect(1).is_ok() => {
                self.uses_secret = true;
                let a = self.lower(&args[0], hint)?;
                let (de, en) = (self.value(&a.de), self.value(&a.en));
                let what = escape(&format!("Secret {}", args[0]));
                R {
                    ty: format!("Secret({})", a.ty),
                    de: F::Template(format!("Decode.secret({{x}}, \"{what}\", {de})")),
                    en: F::Template(format!("Encode.secret({{x}}, {en})")),
                }
            }
            "Int" => {
                self.uses_int = true;
                R::named("Int", "Decode.int", "Encode.int")
            }
            "Int8" | "Int16" | "Int32" | "Int64" => {
                number(&format!("I{}", &name[3..]), &format!("Decode.i{}", &name[3..]))
            }
            "UInt8" | "UInt16" | "UInt32" | "UInt64" => {
                number(&format!("U{}", &name[4..]), &format!("Decode.u{}", &name[4..]))
            }
            "Array" | "Map" | "Maybe" if expect(1).is_ok() => {
                let a = self.lower(&args[0], &format!("{hint}Item"))?;
                let (de, en) = (self.value(&a.de), self.value(&a.en));
                let (ty, helper) = match name {
                    "Array" => (format!("List({})", a.ty), "list"),
                    "Map" => (format!("List((Str, {}))", a.ty), "map"),
                    _ => (format!("[None, Some({})]", a.ty), "maybe"),
                };
                R {
                    ty,
                    de: F::Template(format!("Decode.{helper}({{x}}, {de})")),
                    en: F::Template(format!("Encode.{helper}({{x}}, {en})")),
                }
            }
            "Result" if expect(2).is_ok() => {
                let (e, a) =
                    (self.lower(&args[0], &format!("{hint}Err"))?, self.lower(&args[1], &format!("{hint}Ok"))?);
                let (ade, ede, aen, een) = (self.value(&a.de), self.value(&e.de), self.value(&a.en), self.value(&e.en));
                R {
                    ty: format!("Try({}, {})", a.ty, e.ty),
                    de: F::Template(format!("Decode.result({{x}}, {ade}, {ede})")),
                    en: F::Template(format!("Encode.result({{x}}, {aen}, {een})")),
                }
            }
            "Array" | "Map" | "Maybe" | "Result" | "Secret" => {
                return self.fail(pos, format!("{name} takes arguments"));
            }
            "Stream" => return self.fail(pos, "Stream is only allowed as the whole type of a definition"),
            _ => {
                let hint = match name {
                    "Money" | "Currency" => format!(" (import it with: import @haus/money ({name}))"),
                    _ if STD_TIME.contains(&name) => format!(" (import it with: import std/time ({name}))"),
                    _ => String::new(),
                };
                return self.fail(pos, format!("unknown type {name}{hint}"));
            }
        };
        if !args.is_empty() && !matches!(name, "Array" | "Map" | "Maybe" | "Result" | "Secret") {
            return self.fail(pos, format!("{name} takes no arguments"));
        }
        Ok(r)
    }

    /// A record or variant written inline: a structural type, with helper functions.
    fn inline(&mut self, ty: &Ty, hint: &str) -> Result<R> {
        let s = snake(hint);
        if !self.names.insert(hint.to_owned()) {
            return self.fail(
                ty.pos(),
                format!("the inline type here would be called {hint}, which is taken; give it a name"),
            );
        }
        let (rty, de, en) = match ty {
            Ty::Record { closed, fields, .. } => self.record(hint, *closed, fields)?,
            Ty::Variant { closed: false, cases, .. } if cases.is_empty() => {
                let r = any_tag();
                (r.ty, self.call_body(&r.de), self.call_body(&r.en))
            }
            Ty::Variant { closed, cases, .. } => self.variant(hint, *closed, cases)?,
            _ => return self.fail(ty.pos(), "expected a record or a variant here"),
        };
        // In a generic type, the helpers take the decoders and encoders of the parameters they use.
        let used = params_in(ty);
        let p = Params::new(self.params.iter().filter(|(h, _)| used.contains(h)).map(|(_, p)| (p.clone(), true)));
        let v = encoded_var(ty);
        self.helpers.push(format!(
            "\tdecode_{s} : Value{} -> Try({rty}, Decode.Error)\n\tdecode_{s} = |v{}| {de}\n\n\
             \tencode_{s} : {rty}{} -> Value\n\tencode_{s} = |{v}{}| {en}\n",
            p.de_types, p.de_args, p.en_types, p.en_args
        ));
        Ok(if p.de_args.is_empty() {
            R { ty: rty, de: F::Name(format!("decode_{s}")), en: F::Name(format!("encode_{s}")) }
        } else {
            R {
                ty: rty,
                de: F::Template(format!("decode_{s}({{x}}{})", p.de_args)),
                en: F::Template(format!("encode_{s}({{x}}{})", p.en_args)),
            }
        })
    }

    fn fields(&mut self, owner: &str, fields: &[Field]) -> Result<Vec<(String, &'static str, Field, R)>> {
        let out = fields
            .iter()
            .map(|f| {
                let r = self.lower(&f.ty, &format!("{owner}{}", pascal(&f.key)))?;
                Ok((field_name(&f.key), if f.optional { "optional_field" } else { "field" }, f.clone(), r))
            })
            .collect::<Result<Vec<_>>>()?;
        match out.iter().enumerate().find(|(i, f)| out[..*i].iter().any(|g| g.0 == f.0)) {
            Some((_, (n, _, f, _))) => {
                self.fail(f.pos, format!("fields {} and another one are both {n} in Roc", f.key))
            }
            None => Ok(out),
        }
    }

    /// A record: its type, a decoder body over `v`, and an encoder body over `v`.
    fn record(&mut self, owner: &str, closed: bool, fields: &[Field]) -> Result<(String, String, String)> {
        let fs = self.fields(owner, fields)?;
        let (ty, decode, encode) = self.record_parts(&fs, "v")?;
        let check = if closed { format!("\t\tDecode.closed(fs, [{}])?\n", quoted(fields)) } else { String::new() };
        let fs_name = if fields.is_empty() && !closed { "_fs" } else { "fs" };
        Ok((ty, format!("{{\n\t\t{fs_name} = Decode.strict_record(v)?\n{check}\t\tOk({decode})\n\t}}"), encode))
    }

    /// A record's type, its `{ … }` built from `fs`, and `Encode.record([…])` of the record `var`.
    fn record_parts(&mut self, fs: &[(String, &'static str, Field, R)], var: &str) -> Result<(String, String, String)> {
        let ty = fs
            .iter()
            .map(
                |(n, _, f, r)| {
                    if f.optional { format!("{n} : [Missing, Present({})]", r.ty) } else { format!("{n} : {}", r.ty) }
                },
            )
            .collect::<Vec<_>>()
            .join(", ");
        let decoded = fs
            .iter()
            .map(|(n, how, f, r)| {
                let de = self.value(&r.de);
                format!("{n}: Decode.{how}(fs, \"{}\", {de})?", escape(&f.key))
            })
            .collect::<Vec<_>>()
            .join(", ");
        let encoded = fs
            .iter()
            .map(|(n, _, f, r)| {
                let key = escape(&f.key);
                if f.optional {
                    let en = self.value(&r.en);
                    format!("(\"{key}\", Encode.optional({var}.{n}, {en}))")
                } else {
                    let value = match &r.en {
                        F::Name(f) => format!("{f}({var}.{n})"),
                        F::Template(t) => t.replace("{x}", &format!("{var}.{n}")),
                    };
                    format!("(\"{key}\", Present({value}))")
                }
            })
            .collect::<Vec<_>>()
            .join(", ");
        Ok((format!("{{ {ty} }}"), format!("{{ {decoded} }}"), format!("Encode.record([{encoded}])")))
    }

    /// A variant: its tag union, a decoder body over `v`, and an encoder body over `v`.
    fn variant(&mut self, owner: &str, closed: bool, cases: &[Case]) -> Result<(String, String, String)> {
        if let Some(case) = cases.iter().find(|c| !closed && c.tag == "Unknown") {
            return self.fail(
                case.pos,
                "an open variant can't have a tag Unknown in Roc (unknown tags decode to Unknown); close it",
            );
        }
        let (mut tags, mut de, mut en, mut arity) = (vec![], vec![], vec![], vec![]);
        for case in cases {
            let tag = &case.tag;
            let hint = format!("{owner}{tag}");
            match case.payload.as_slice() {
                [] => {
                    tags.push(tag.clone());
                    de.push(format!("Tag(\"{tag}\", []) => Ok({tag})"));
                    en.push(format!("{tag} => Tag(\"{tag}\", [])"));
                    arity.push(format!("Tag(\"{tag}\", _) => Decode.arity(\"{tag}\", 0)"));
                }
                [Ty::Record { closed: rc, fields, .. }] => {
                    let fs = self.fields(&hint, fields)?;
                    let (ty, decoded, encoded) = self.record_parts(&fs, "r")?;
                    let check =
                        if *rc { format!("Decode.closed(fs, [{}])?\n\t\t\t", quoted(fields)) } else { String::new() };
                    tags.push(format!("{tag}({ty})"));
                    // `Tag {}`: no fields to read or write.
                    let (fs, r) = if fields.is_empty() { (if *rc { "fs" } else { "_fs" }, "_r") } else { ("fs", "r") };
                    de.push(format!(
                        "Tag(\"{tag}\", [p]) => Decode.payload(\"{tag}\", p, |{fs}| {{\n\t\t\t{check}Ok({tag}({decoded}))\n\t\t}})"
                    ));
                    en.push(format!("{tag}({r}) => Tag(\"{tag}\", [{encoded}])"));
                    arity.push(format!("Tag(\"{tag}\", _) => Decode.arity(\"{tag}\", 1)"));
                }
                items => {
                    let rs = items
                        .iter()
                        .enumerate()
                        .map(|(i, t)| {
                            self.lower(t, &if items.len() == 1 { hint.clone() } else { format!("{hint}{i}") })
                        })
                        .collect::<Result<Vec<_>>>()?;
                    let vars: Vec<String> = (0..rs.len()).map(|i| format!("a{i}")).collect();
                    tags.push(format!("{tag}({})", rs.iter().map(|r| r.ty.clone()).collect::<Vec<_>>().join(", ")));
                    let values = rs
                        .iter()
                        .zip(&vars)
                        .enumerate()
                        .map(|(i, (r, var))| {
                            let f = self.value(&r.de);
                            format!("Decode.arg(\"{tag}\", {i}, {var}, {f})?")
                        })
                        .collect::<Vec<_>>()
                        .join(", ");
                    de.push(format!("Tag(\"{tag}\", [{}]) => Ok({tag}({values}))", vars.join(", ")));
                    let encoded = rs
                        .iter()
                        .zip(&vars)
                        .map(|(r, var)| match &r.en {
                            F::Name(f) => format!("{f}({var})"),
                            F::Template(t) => t.replace("{x}", var),
                        })
                        .collect::<Vec<_>>()
                        .join(", ");
                    en.push(format!("{tag}({}) => Tag(\"{tag}\", [{encoded}])", vars.join(", ")));
                    arity.push(format!("Tag(\"{tag}\", _) => Decode.arity(\"{tag}\", {})", rs.len()));
                }
            }
        }
        let names = cases.iter().map(|c| format!("\"{}\"", c.tag)).collect::<Vec<_>>().join(", ");
        if closed {
            de.extend(arity);
            de.push(format!("Tag(tag, _) => Decode.unknown_tag(tag, [{names}])"));
        } else {
            tags.push("Unknown(Str, List(Value))".into());
            de.extend(arity);
            de.push("Tag(tag, args) => Ok(Unknown(tag, args))".into());
            en.push("Unknown(tag, args) => Tag(tag, args)".into());
        }
        de.push(format!("_ => Decode.expected(\"a variant ({owner})\", v)"));
        let arms = |arms: &[String]| arms.iter().map(|a| format!("\t\t{a}\n")).collect::<String>();
        Ok((
            format!("[{}]", tags.join(", ")),
            format!("match v {{\n{}\t}}", arms(&de)),
            format!("match v {{\n{}\t}}", arms(&en)),
        ))
    }
}

/// The parameters of a generic definition or helper, as Roc code: the types
/// and names of the decoders and encoders that come after `v`.
struct Params {
    de_types: String,
    de_args: String,
    en_types: String,
    en_args: String,
}

impl Params {
    /// Each parameter, and whether it is used (`_decode_a` when not).
    fn new(params: impl Iterator<Item = (String, bool)>) -> Params {
        params.fold(
            Params { de_types: String::new(), de_args: String::new(), en_types: String::new(), en_args: String::new() },
            |mut p, (name, used)| {
                let unused = if used { "" } else { "_" };
                let _ = write!(p.de_types, ", (Value -> Try({name}, Decode.Error))");
                let _ = write!(p.de_args, ", {unused}decode_{name}");
                let _ = write!(p.en_types, ", ({name} -> Value)");
                let _ = write!(p.en_args, ", {unused}encode_{name}");
                p
            },
        )
    }
}

/// The encoder's parameter: `_v` for `{}`, whose encoder doesn't read it.
fn encoded_var(ty: &Ty) -> &'static str {
    match ty {
        Ty::Record { fields, .. } if fields.is_empty() => "_v",
        _ => "v",
    }
}

/// The type parameters a type expression uses.
fn params_in(ty: &Ty) -> HashSet<String> {
    let mut out = HashSet::new();
    walk(ty, &mut |t| {
        if let Ty::Param { name, .. } = t {
            out.insert(name.clone());
        }
    });
    out
}

/// Every type expression in `ty`, `ty` included.
fn walk(ty: &Ty, f: &mut impl FnMut(&Ty)) {
    f(ty);
    match ty {
        Ty::Param { .. } => {}
        Ty::Name { args, .. } => args.iter().for_each(|a| walk(a, f)),
        Ty::Record { fields, .. } => fields.iter().for_each(|x| walk(&x.ty, f)),
        Ty::Variant { cases, .. } => cases.iter().flat_map(|c| &c.payload).for_each(|t| walk(t, f)),
    }
}

/// Whether a definition refers to itself, directly or through other definitions.
fn refers_to_itself(def: &TypeDef, defs: &HashMap<&str, &TypeDef>) -> bool {
    let names = |ty: &Ty| {
        let mut out = Vec::new();
        walk(ty, &mut |t| {
            if let Ty::Name { name, .. } = t
                && defs.contains_key(name.as_str())
            {
                out.push(name.clone());
            }
        });
        out
    };
    let (mut seen, mut todo) = (HashSet::new(), names(&def.ty));
    while let Some(name) = todo.pop() {
        if name == def.name {
            return true;
        }
        if seen.insert(name.clone()) {
            todo.extend(names(&defs[name.as_str()].ty));
        }
    }
    false
}

/// Doc lines for what is deprecated in a definition (spec §14), since Roc has
/// no marker for it: the type itself, and its fields and tags, inline ones too.
fn deprecations(def: &TypeDef) -> Vec<String> {
    fn line(what: &str, attrs: &[Attribute]) -> Option<String> {
        deprecation(attrs).map(|why| match why {
            Some(why) => format!("Deprecated{what}: {why}"),
            None => format!("Deprecated{what}."),
        })
    }
    fn ty(t: &Ty, path: &str, out: &mut Vec<String>) {
        match t {
            Ty::Name { args, .. } => args.iter().for_each(|a| ty(a, path, out)),
            Ty::Param { .. } => {}
            Ty::Record { fields, .. } => fields.iter().for_each(|f| {
                let at = format!("{path}{}", f.key);
                out.extend(line(&format!(" field `{at}`"), &f.attrs));
                ty(&f.ty, &format!("{at}."), out);
            }),
            Ty::Variant { cases, .. } => cases.iter().for_each(|c| {
                let at = format!("{path}{}", c.tag);
                out.extend(line(&format!(" tag `{at}`"), &c.attrs));
                c.payload.iter().for_each(|p| ty(p, &format!("{at}."), out));
            }),
        }
    }
    let mut out: Vec<String> = line("", &def.attrs).into_iter().collect();
    ty(&def.ty, "", &mut out);
    if !out.is_empty() {
        out.insert(0, String::new());
    }
    out
}

/// Roc's builtin types: a schema type with one of these names gets a `_` in Roc.
const BUILTIN_TYPES: &[&str] = &[
    "Str",
    "Bool",
    "List",
    "Dict",
    "Set",
    "Box",
    "Try",
    "Dec",
    "F32",
    "F64",
    "I8",
    "I16",
    "I32",
    "I64",
    "I128",
    "U8",
    "U16",
    "U32",
    "U64",
    "U128",
    "Stream",
    "Iter",
    "Utf8Problem",
    "Num",
];

/// `< >`: any tag.
fn any_tag() -> R {
    R::named("[Bare(Str), Other(Str, List(Value))]", "Decode.any_tag", "Encode.any_tag")
}

fn quoted(fields: &[Field]) -> String {
    fields.iter().map(|f| format!("\"{}\"", escape(&f.key))).collect::<Vec<_>>().join(", ")
}

fn escape(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"").replace('$', "\\$")
}

/// `deliverTo` → `DeliverTo`, `money` → `Money`.
fn pascal(s: &str) -> String {
    s.split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|w| !w.is_empty())
        .map(|w| w[..1].to_ascii_uppercase() + &w[1..])
        .collect()
}

/// `DeliverTo` → `deliver_to`.
fn snake(s: &str) -> String {
    s.chars().enumerate().fold(String::new(), |mut out, (i, c)| {
        match c {
            c if c.is_ascii_uppercase() => {
                if i > 0 && !out.ends_with('_') {
                    out.push('_');
                }
                out.push(c.to_ascii_lowercase());
            }
            c if c.is_ascii_alphanumeric() => out.push(c),
            _ if !out.ends_with('_') && !out.is_empty() => out.push('_'),
            _ => {}
        }
        out
    })
}

/// Words a Roc field can't be called.
const KEYWORDS: &[&str] = &[
    "if", "else", "match", "when", "is", "as", "import", "expect", "dbg", "crash", "return", "var", "for", "while",
    "and", "or", "has", "where", "module", "package", "app", "platform", "exposing", "break", "continue",
];

/// A field name in Roc: `deliverTo` → `deliver_to`, `type` → `type`, `if` → `if_`.
fn field_name(key: &str) -> String {
    match snake(key) {
        s if s.is_empty() => "field".into(),
        s if s.starts_with(|c: char| c.is_ascii_digit()) => format!("f{s}"),
        s if KEYWORDS.contains(&s.as_str()) => format!("{s}_"),
        s => s,
    }
}

#[cfg(test)]
mod tests {
    use super::generate;
    use crate::packages::Packages;

    fn roc(schema: &str) -> String {
        generate(schema, "M", "m", &[], &Packages::none()).unwrap_or_else(|e| panic!("{e}"))
    }

    #[test]
    fn floats_have_their_own_types() {
        let code = roc("type A = { x: Float32, y: Float64 }");
        assert!(code.contains("A : { x : F32, y : F64 }"), "{code}");
        assert!(code.contains("Decode.f32") && code.contains("Encode.f32"), "{code}");
    }

    #[test]
    fn names_of_roc_builtins_get_an_underscore() {
        let code = roc("type F64 = Float64\ntype Box = { w: Int }\ntype Value = Box");
        assert!(code.contains("F64_ : F64") && code.contains("Box_ : { w : Int }"), "{code}");
        assert!(code.contains("Value_ : Box_") && code.contains("decode_value = |v| decode_box(v)"), "{code}");
    }

    #[test]
    fn generic_types_take_decoders_and_encoders() {
        let code = roc("type Pair a = { first: a, second: a }\ntype Ints = Pair Int");
        assert!(
            code.contains("decode_pair : Value, (Value -> Try(a, Decode.Error)) -> Try(Pair(a), Decode.Error)"),
            "{code}"
        );
        assert!(code.contains("encode_pair : Pair(a), (a -> Value) -> Value"), "{code}");
        assert!(code.contains("decode_ints = |v| decode_pair(v, Decode.int)"), "{code}");
    }

    #[test]
    fn any_and_secret() {
        let code = roc("type A = { key: Secret String, pins: Array (Secret UInt16), extra: Any }");
        assert!(code.contains("import haus.Secret\n"), "{code}");
        assert!(code.contains("A : { key : Secret(Str), pins : List(Secret(U16)), extra : Value }"), "{code}");
        assert!(
            code.contains("Decode.field(fs, \"key\", |x4| Decode.secret(x4, \"Secret String\", Decode.str))?"),
            "{code}"
        );
        assert!(code.contains("Decode.field(fs, \"extra\", Decode.any)?"), "{code}");
        assert!(code.contains("(\"key\", Present(Encode.secret(v.key, Encode.str)))"), "{code}");
        assert!(!roc("type A = Int").contains("haus.Secret"));
    }

    #[test]
    fn deprecations_are_doc_comments() {
        let code = roc(
            "// A client.\n@deprecated(\"use Customer\")\ntype Client = { id: Int, @deprecated(\"use email\") mail?: String, \
             shape: < Circle | @deprecated Square > }",
        );
        assert!(
            code.contains(
                "\t## A client.\n\t##\n\t## haus type `m#Client`.\n\t##\n\t## Deprecated: use Customer\n\
                 \t## Deprecated field `mail`: use email\n\t## Deprecated tag `shape.Square`.\n"
            ),
            "{code}"
        );
    }

    #[test]
    fn types_that_refer_to_themselves_are_nominal() {
        let code = roc("type Tree = { kids: Array Tree }\ntype List a = < Nil | Cons a (List a) >\ntype N = Array N");
        assert!(code.contains("Tree := { kids : List(Tree) }"), "{code}");
        assert!(code.contains("List_(a) := [Nil, Cons(a, List_(a)), Unknown(Str, List(Value))]"), "{code}");
        assert!(code.contains("N := [N(List(N))]"), "{code}");
    }
}
